{
  "title": "夜光之城",
  "scene": "你来到了一个巨大的城市，到处都是闪烁的霓虹灯和高楼大厦。这里的人们很多都有机械义肢，看起来很强壮。在城市中心，有一座非常高的塔，那就是巨型企业'光之源'的总部。你发现有一个小孩在角落里玩着一个看起来很旧的玩具机器人，他似乎对周围的一切都不感兴趣。你注意到玩具机器人发出的声音和安保机器人的声音有些相似。",
  "goal": "潜入'光之源'总部",
  "clue": "角落里的小孩和玩具机器人",
  "choices": [
    {
      "id": "A",
      "text": "尝试黑掉安保机器人",
      "outcome": "你拿出了一些黑客工具，但安保机器人太复杂，你被发现了。现在你需要躲起来，等待安保机器人巡逻结束，这会浪费很多时间。",
      "result": "fail",
      "next": "retry"
    },
    {
      "id": "B",
      "text": "询问小孩玩具机器人的秘密",
      "outcome": "小孩很高兴你对他的机器人感兴趣，告诉你这机器人能模仿其他机器人的声音。你利用这个玩具机器人模仿了安保机器人的声音，成功骗过了门口的机器人们，顺利进入了'光之源'总部。",
      "result": "success",
      "next": "next_level"
    },
    {
      "id": "C",
      "text": "直接强行闯入",
      "outcome": "你冲向大门，安保机器人立刻发现了你。你被电击枪击中，虽然没有受伤，但被保安带到了一个小房间，浪费了许多时间。你必须找到其他方法离开这里。",
      "result": "fail",
      "next": "retry"
    }
  ]
}
